export const fields=[['title','Тапсырма атауы','Мысалы: кофехана тапсырыстарын автоматтандыру'],['context','Ағымдағы жағдай','Қазір үдеріс қалай жұмыс істейді?'],['need','Қажеттілік','Қандай мәселені шешу қажет?'],['users','Пайдаланушылар','Шешімді кім қолданады?'],['data','Деректер мен материалдар','Қандай кесте, мысал немесе дереккөз бар?'],['constraints','Шектеулер','Мерзім, технология және қолжетімділік шектері'],['result','Күтілетін нәтиже','Команда нақты не тапсыруы керек?'],['success','Табыс критерийлері','Нәтижені қандай өлшеммен қабылдайсыз?'],['contact','Байланыс','Байланысуға арналған пошта'],['interaction','Жұмыс форматы','Кеңес беру жиілігі мен кері байланыс тәртібі']];
export const rubric=[{label:'Жағдай мен қажеттілік',weight:20,keys:['context','need'],question:'Қазір не болып жатыр және нақты нені өзгерткіңіз келеді?'},{label:'Деректер мен материалдар',weight:20,keys:['data'],question:'Командаға қандай деректер, мысалдар немесе дереккөздер бере аласыз?'},{label:'Күтілетін нәтиже',weight:15,keys:['result'],question:'Жұмыс соңында команда қандай нақты нәтиже тапсыруы керек?'},{label:'Табыс критерийлері',weight:15,keys:['success'],question:'Қандай өлшенетін белгілер бойынша нәтижені қабылдайсыз?'},{label:'Шектеулер',weight:10,keys:['constraints'],question:'Мерзім, технология, бюджет немесе қолжетімділік бойынша қандай шектеу бар?'},{label:'Пайдаланушылар',weight:10,keys:['users'],question:'Шешімді кім және қандай жағдайда қолданады?'},{label:'Бизнеспен байланыс',weight:10,keys:['contact','interaction'],question:'Кіммен байланысу керек және кеңес пен кері байланыс қалай ұйымдастырылады?'}];
export const topics=['Сауда','Қызмет көрсету','Білім','Логистика','Тамақтану'];
export const blank=()=>Object.fromEntries(fields.map(([k])=>[k,'']));
export const filled=s=>typeof s==='string'&&s.trim().length>0;
export function breakdown(card={}){return rubric.map(r=>({...r,points:r.keys.every(k=>filled(card[k]))?r.weight:0,missing:r.keys.filter(k=>!filled(card[k]))}))}
export const score=card=>breakdown(card).reduce((n,r)=>n+r.points,0);
export function readiness(n){return n<40?'Нақтылау қажет':n<70?'Жұмысқа жарамды':n<90?'Дайын':'Басым'}
export function analyze(input){const missing=rubric.filter(r=>r.keys.some(k=>!filled(input.card?.[k])));const base=missing.map(r=>({keys:r.keys,question:r.question}));for(const r of rubric){if(base.length>=3)break;if(!base.some(q=>q.question===r.question))base.push({keys:r.keys,question:r.question+' Қажет болса, бар жауабыңызды нақтылаңыз.'})}return{questions:base,missing:missing.flatMap(r=>r.keys.filter(k=>!filled(input.card?.[k]))),card:{...blank(),...Object.fromEntries(fields.map(([k])=>[k,String(input.card?.[k]||'')]))}}}
export function validateAI(output,input){if(!output||!Array.isArray(output.questions)||output.questions.length<3||!output.questions.every(q=>typeof q.question==='string'&&q.question.trim()&&Array.isArray(q.keys)&&q.keys.every(k=>fields.some(f=>f[0]===k)))||!Array.isArray(output.missing)||!output.card)throw Error('AI жауабының құрылымы жарамсыз. Енгізілген мәтін сақталды. Қайта талдап көріңіз.');for(const [k]of fields)if(output.card[k]!==String(input.card?.[k]||''))throw Error('AI пайдаланушы растамаған дерек қосты. Жауап қабылданбады.');return output}
export const prompt='Сен қазақ тіліндегі бизнес тапсырмасын нақтылау көмекшісісің. Тек кірісте берілген ақпаратты пайдалан. Жоқ деректерді ойдан қоспа. Бос өрістерді тап, кемінде 3 орынды сұрақ қой. card өрістерін өзгеріссіз қайтар. JSON пішімі: {questions:[{keys:[өріс],question:мәтін}],missing:[өріс],card:{өріс:мәтін}}. Рейтингті есептеме, команданы таңдама. Жариялауды адам растайды.';
export function safeURL(value){try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.href:null}catch{return null}}
export function acceptStage(proposal){if(proposal.status!=='Таңдалды'||proposal.stage.status!=='Тексеруде')throw Error('Алдымен таңдалған команда нәтиже ұсынуы керек.');proposal.stage.status='Расталды';proposal.stage.points=20;return proposal}
export function seed(){const teams=[['t1','Qadam','Сауда, логистика','Деректерді талдау, интерфейс','Python, React'],['t2','Orken','Білім, қызмет көрсету','UX зерттеу, прототип','Figma, JavaScript'],['t3','Sana Lab','Тамақтану, сауда','Автоматтандыру, веб әзірлеу','Node.js, SQL'],['t4','Birim','Логистика, қызмет көрсету','API, үдерістерді талдау','Python, PostgreSQL'],['t5','Jana','Білім, сауда','Тестілеу, интерфейс','TypeScript, React']].map(([id,name,interests,skills,tech])=>({id,name,interests,skills,tech}));
const descriptions=['Кофеханадағы тапсырысты жеңілдеткіміз келеді.','Дүкендегі тауар қалдығын көру қиын. Excel кестесі бар.','Оқу орталығында сабаққа қатысуды тіркеу қажет.','Жеткізу бағыттарын жоспарлауға көп уақыт кетеді.','Клиенттердің қызмет туралы пікірін бір жерге жинағымыз келеді.'];
const titles=['Кофеханаға тапсырыс қабылдау жүйесі','Дүкендегі тауар қалдығын бақылау','Оқу орталығындағы қатысу есебі','Жеткізу бағытын жоспарлау','Клиент пікірлерін жинау'];
const contexts=['Тапсырыс қағазға жазылады, баристаға ауызша беріледі.','Тауар қалдығы әр күннің соңында Excel-де жаңартылады.','Оқытушы қатысуды қағаз журналға белгілейді.','Диспетчер күн сайын бағытты қолмен құрады.','Пікірлер бірнеше чатта қалып, жүйелі қаралмайды.'];
const cats=['Тамақтану','Сауда','Білім','Логистика','Қызмет көрсету'];
const cards=titles.map((title,i)=>({...blank(),title,context:contexts[i],need:descriptions[i],users:['Кассир мен бариста','Қоймашы мен дүкен иесі','Оқытушылар мен әкімші','Диспетчер мен курьер','Әкімші мен клиенттер'][i],data:'Жеке дерексіз 20 синтетикалық жазба және қолданыстағы кесте үлгісі.',constraints:'Оқу прототипі 14 күнде дайын болсын. Нақты клиент деректерін қолданбау.',result:'Браузерде ашылатын прототип, бастапқы код және қысқа нұсқаулық.',success:'20 тест жазбасының бәрі сақталып, сүзгі арқылы қатесіз табылуы керек.',contact:'business-demo@example.com',interaction:'Аптасына екі рет 20 минуттық кеңес; кері байланыс 2 жұмыс күнінде беріледі.'}));
cards[1].data='';cards[2].data='';cards[2].success='';cards[2].constraints='';cards[3].data='';cards[3].result='';cards[3].success='';cards[3].constraints='';cards[3].contact='';cards[3].interaction='';cards[4].data='';cards[4].success='';
const tasks=cards.map((card,i)=>({id:'p'+(i+1),owner:i%2?'b2':'b1',topic:cats[i],raw:descriptions[i],working:{...card},confirmed:{...card},published:true,revision:1,synthetic:true,updated:Date.now()-i*1000}));
const drafts=descriptions.map((raw,i)=>({id:'d'+(i+1),owner:'b1',topic:cats[i],raw,working:{...blank(),title:titles[i],context:raw},confirmed:null,published:false,revision:0,synthetic:true,updated:Date.now()}));
const proposals=teams.map((t,i)=>({id:'r'+i,taskId:'p'+(i%2+1),teamId:t.id,idea:'Қажеттілікті зерттеп, деректерді енгізу және іздеу интерфейсін ұсынамыз.',plan:'1. Бизнеспен сұхбат. 2. Прототип әзірлеу. 3. 20 тест жазбасымен тексеру.',days:10+i,url:'https://example.com/prototype-'+(i+1),status:'Күтуде',synthetic:true,stage:{status:'Ұсынылмаған',description:'',url:'',points:0}}));return{version:2,tasks:[...tasks,...drafts],teams,proposals,role:'business',actor:'b1'};}

